import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Create your first project","description":"Create the first administrator, model channels, and a project ready for its first full-project analysis.","frontmatter":{"page_id":"guide-create-first-project","description":"Create the first administrator, model channels, and a project ready for its first full-project analysis."},"headers":[],"relativePath":"en/guide/create-first-project.md","filePath":"en/guide/create-first-project.md","lastUpdated":1786289447000}'),n={name:"en/guide/create-first-project.md"};function i(s,e,l,p,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="create-your-first-project" tabindex="-1">Create your first project <a class="header-anchor" href="#create-your-first-project" aria-label="Permalink to &quot;Create your first project&quot;">​</a></h1><p>This page starts with the first browser visit and ends with a project and repository in the workspace. It also creates the first run, but it does not assume that the analysis has already completed.</p><p>Before continuing, make sure the API, Worker, and frontend are running. The Worker is required for the first analysis. With only the API running, a run can enter the queue but cannot analyze the repository.</p><h2 id="step-1-create-the-first-administrator" tabindex="-1">Step 1: Create the first administrator <a class="header-anchor" href="#step-1-create-the-first-administrator" aria-label="Permalink to &quot;Step 1: Create the first administrator&quot;">​</a></h2><p>Open <code>http://localhost:3000</code>. A new database takes you to initial administrator setup.</p><p>Enter:</p><ul><li>an email address;</li><li>an optional display name;</li><li>a password of at least eight characters; and</li><li>the same password for confirmation.</li></ul><p>After submission, the first user becomes a system administrator and is taken to the model channels page. If you see the sign-in form instead, the database already contains a user. Sign in with an existing account instead of trying to initialize the system again.</p><h2 id="step-2-prepare-model-channels" tabindex="-1">Step 2: Prepare model channels <a class="header-anchor" href="#step-2-prepare-model-channels" aria-label="Permalink to &quot;Step 2: Prepare model channels&quot;">​</a></h2><p>An analysis run requires at least one enabled large language model (LLM) channel. Model channels are stored through the web administration area, not in <code>.env</code>.</p><p>When creating a channel:</p><ol><li>Select a provider and the <code>llm</code> capability.</li><li>Enter the model name, API key, and any endpoint required by the provider.</li><li>Use the connection or model test offered by the page to check the settings.</li><li>Save the channel and leave it enabled.</li></ol><p>The saved channel should appear in the model channel list and in the LLM channel selector on the new-project form.</p><p>If you also want semantic or hybrid search, create a separate <code>embedding</code> channel. Each channel stores one capability, so an LLM and an embedding model cannot share one channel. Without an embedding channel, do not expect a semantic index to be available.</p><div class="tip custom-block"><p class="custom-block-title">Secret transport</p><p>The frontend permits passwords and API keys over a localhost connection. When accessed through another hostname, it requires HTTPS. Never submit production secrets over plain HTTP.</p></div><h2 id="step-3-enter-project-details" tabindex="-1">Step 3: Enter project details <a class="header-anchor" href="#step-3-enter-project-details" aria-label="Permalink to &quot;Step 3: Enter project details&quot;">​</a></h2><p>Open <strong>Projects</strong> and choose <strong>Create project</strong>.</p><ol><li>Enter a project name. The page generates a slug, which you can edit before submitting.</li><li>Add a description if it will help other readers.</li><li>Choose public or private visibility according to the access you intend to grant.</li><li>Select the default LLM channel. Select the embedding channel too if you created one.</li></ol><p>At this point, the create button should be available, both the name and slug should be non-empty, and the saved channels should appear in their selectors.</p><h2 id="step-4-add-a-repository" tabindex="-1">Step 4: Add a repository <a class="header-anchor" href="#step-4-add-a-repository" aria-label="Permalink to &quot;Step 4: Add a repository&quot;">​</a></h2><p>A project can contain more than one repository. For the first attempt, add one repository that you know Ershu can read so that failures are easier to isolate.</p><p>The form accepts:</p><ul><li>a GitHub repository URL;</li><li>a GitLab repository URL; or</li><li>a local path visible to the Ershu services.</li></ul><p>Enter the repository name, type, URL or local path, and default branch. A path visible on the computer running the browser is not necessarily visible to the API and Worker. A local repository path must be readable by the processes that actually run Ershu.</p><p>The new-project form does not collect credentials for a private remote repository. If the repository needs a token or SSH key, create the project first, configure the credential from the project&#39;s <strong>Repositories</strong> page, and only then start a run.</p><h2 id="step-5-create-the-project-and-verify-it" tabindex="-1">Step 5: Create the project and verify it <a class="header-anchor" href="#step-5-create-the-project-and-verify-it" aria-label="Permalink to &quot;Step 5: Create the project and verify it&quot;">​</a></h2><p>Choose <strong>Create</strong>. A successful request takes you to the new project overview.</p><p>Confirm that:</p><ul><li>the project name and description are correct;</li><li>the project has the intended public or private visibility;</li><li>the repository count is correct; and</li><li>the repository appears on the <strong>Repositories</strong> page.</li></ul><p>Creating a project does not start an analysis. It is normal for Docs and Search to have no new content at this point.</p><h2 id="step-6-create-the-first-run" tabindex="-1">Step 6: Create the first run <a class="header-anchor" href="#step-6-create-the-first-run" aria-label="Permalink to &quot;Step 6: Create the first run&quot;">​</a></h2><p>Make sure the Worker is still running. Open the project&#39;s <strong>Runs</strong> page and choose <strong>New run</strong>.</p><p>The first analysis has two required settings:</p><ol><li>Select <strong>Full project</strong> (<code>full_project</code>) as the run type.</li><li>Include every active repository in the project.</li></ol><p>The page locks this scope until the full-project baseline exists. Do not try to bypass the baseline with a repository or incremental run. Leave the branch empty to use repository defaults, and keep the project&#39;s default LLM and embedding channels unless you intentionally need different ones.</p><p>After submission, the new run appears at the top of the list, usually as queued or another active status. This only confirms that the API accepted the request. Continue with <a href="./follow-a-run">following the first analysis</a> until the Worker finishes it.</p>',36)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
